import React, { useEffect, useState } from 'react';
import '../App.css';
import './DynamicTable.css';
import { formatRupee } from '../utils/dataUtils';

// Utility function to filter payments due in a selected month.
//
// A payment's `date` is treated as its start date, not a one-off due date:
//   - Monthly EMIs (paymentType === 'm') are due EVERY month once they have
//     started, so they should appear in the selected month as long as their
//     start date is on/before the end of that month.
//   - Yearly EMIs (paymentType === 'y') are due once a year, so they only
//     appear when the selected month matches their start month (and they have
//     started).
//   - Anything without a recurring paymentType falls back to the original
//     "same calendar month" behaviour.
const getMonthPayments = (payments, selectedDate) => {
  const selectedMonth = selectedDate.getMonth();
  const selectedYear = selectedDate.getFullYear();

  return (payments || []).filter(({ date, paymentType }) => {
    if (!date) return false;
    const start = new Date(date);
    if (isNaN(start.getTime())) return false;

    const startedBySelectedMonth =
      start.getFullYear() < selectedYear ||
      (start.getFullYear() === selectedYear && start.getMonth() <= selectedMonth);

    if (paymentType === 'm') {
      return startedBySelectedMonth;
    }

    if (paymentType === 'y') {
      return startedBySelectedMonth && start.getMonth() === selectedMonth;
    }

    return start.getMonth() === selectedMonth && start.getFullYear() === selectedYear;
  });
};

const STORAGE_KEY = 'paymentDoneChecklist';

const PaymentSummaryTable = ({ payments }) => {
  const [selectedDate, setSelectedDate] = useState(() => new Date());

  const currentMonthPayments = getMonthPayments(payments, selectedDate);
  const currentMonthName = selectedDate.toLocaleString('default', {
    month: 'long',
    year: 'numeric',
  });
  const currentMonthTotal = currentMonthPayments.reduce(
    (sum, { paymentAmount }) => sum + (Number(paymentAmount) || 0),
    0
  );

  const [doneMap, setDoneMap] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};
    } catch {
      return {};
    }
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(doneMap));
  }, [doneMap]);

  const toggleDone = (key) => {
    setDoneMap((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const changeMonth = (offset) => {
    setSelectedDate((prev) => new Date(prev.getFullYear(), prev.getMonth() + offset, 1));
  };

  return (
    <div className="table-container">
      <h3>Payments for {currentMonthName}</h3>
      <table className="responsive-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Payment Type</th>
            <th>Amount</th>
            <th>Date</th>
            <th>Done</th>
          </tr>
        </thead>
        <tbody>
          {currentMonthPayments.length > 0 ? (
            <>
              {currentMonthPayments.map(({ name, paymentType, date, paymentAmount }, index) => {
              const key = `${name}_${date}_${selectedDate.getFullYear()}_${selectedDate.getMonth()}`;
              const done = !!doneMap[key];
              return (
                <tr key={index} style={{ opacity: done ? 0.5 : 1 }}>
                  <td style={{ textDecoration: done ? 'line-through' : 'none' }}>{name}</td>
                  <td>{paymentType === 'm' ? 'Monthly' : 'Yearly'}</td>
                  <td>{formatRupee(paymentAmount)}</td>
                  <td>{new Date(date).toLocaleDateString()}</td>
                  <td style={{ textAlign: 'center' }}>
                    <input
                      type="checkbox"
                      checked={done}
                      onChange={() => toggleDone(key)}
                      style={{ width: '18px', height: '18px', cursor: 'pointer' }}
                    />
                  </td>
                </tr>
              );
              })}
              <tr>
                <td colSpan="2"><strong>Total </strong></td>
                <td colSpan="3"><strong>{formatRupee(currentMonthTotal)}</strong></td>
              </tr>
            </>
          ) : (
            <tr>
              <td colSpan="5">No payments for this month</td>
            </tr>
          )}
        </tbody>
      </table>

      <div style={{ marginBottom: '10px' }}>
        <button
          onClick={() => changeMonth(-1)}
          aria-label="Previous month"
        >
          &lt;
        </button>
        <span style={{ margin: '0 8px', fontWeight: 'bold' }}>{currentMonthName}</span>
        <button
          onClick={() => changeMonth(1)}
          aria-label="Next month"
        >
          &gt;
        </button>
      </div>
    </div>
  );
};

export default PaymentSummaryTable;
