import { useState } from "react";
import "../App.css";
import "./DynamicTable.css";
import { formatRupee } from "../utils/dataUtils";

const STORAGE_KEY = "balance_tracker_gold";
const GOLD_ITEMS_KEY = "gold_item_types";

const loadGoldItemTypes = () => {
  try {
    const saved = localStorage.getItem(GOLD_ITEMS_KEY);
    return saved ? JSON.parse(saved) : [];
  } catch {
    return [];
  }
};

const saveGoldItemTypes = (items) => {
  localStorage.setItem(GOLD_ITEMS_KEY, JSON.stringify(items));
};

const createGoldItem = () => ({ name: "", quantity: "" });

const emptyForm = {
  items: [createGoldItem()],
  vendor: "",
  balance: "",
  purchaseDate: "",
  papers: "",
};

const loadGoldPurchases = () => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : [];
  } catch (error) {
    console.error("Error loading gold purchases:", error);
    return [];
  }
};

const formatDate = (date) => {
  if (!date) return "-";
  const [year, month, day] = date.split("-");
  return year && month && day ? `${day}/${month}/${year}` : date;
};

// Existing Gold entries used one set of name/quantity fields. Treat
// them as a one-item purchase so old saved data stays visible and editable.
const getPurchaseItems = (purchase) =>
  Array.isArray(purchase.items) && purchase.items.length > 0
    ? purchase.items
    : [{
        name: purchase.name || "",
        quantity: purchase.quantity ?? "",
      }];

const getTotalQuantity = (items) =>
  items.reduce((sum, item) => sum + (parseFloat(item.quantity) || 0), 0);

const GoldAssetsComponent = () => {
  const [purchases, setPurchases] = useState(loadGoldPurchases);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [selectedPurchase, setSelectedPurchase] = useState(null);

  // Gold item types master list
  const [goldItemTypes, setGoldItemTypes] = useState(loadGoldItemTypes);
  const [showItemsPanel, setShowItemsPanel] = useState(false);
  const [newItemType, setNewItemType] = useState("");

  // Gold price per 8g (stored in localStorage)
  const [price8g, setPrice8g] = useState(() => {
    const saved = localStorage.getItem("gold_price_8g");
    return saved || "";
  });

  const handlePrice8gChange = (val) => {
    setPrice8g(val);
    localStorage.setItem("gold_price_8g", val);
  };

  const savePurchases = (updatedPurchases) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedPurchases));
    setPurchases(updatedPurchases);
  };

  const handleAddItemType = () => {
    const trimmed = newItemType.trim();
    if (!trimmed || goldItemTypes.includes(trimmed)) return;
    const updated = [...goldItemTypes, trimmed];
    saveGoldItemTypes(updated);
    setGoldItemTypes(updated);
    setNewItemType("");
  };

  const handleRemoveItemType = (item) => {
    const updated = goldItemTypes.filter((i) => i !== item);
    saveGoldItemTypes(updated);
    setGoldItemTypes(updated);
  };

  const handleChange = ({ target: { name, value } }) => {
    setForm((current) => ({ ...current, [name]: value }));
  };

  const handleItemChange = (index, field, value) => {
    setForm((current) => ({
      ...current,
      items: current.items.map((item, itemIndex) =>
        itemIndex === index ? { ...item, [field]: value } : item
      ),
    }));
  };

  const addItem = () => {
    setForm((current) => ({ ...current, items: [...current.items, createGoldItem()] }));
  };

  const removeItem = (index) => {
    setForm((current) => ({
      ...current,
      items: current.items.filter((_, itemIndex) => itemIndex !== index),
    }));
  };

  const resetForm = () => {
    setForm(emptyForm);
    setEditingId(null);
    setShowForm(false);
  };

  const beginAdd = () => {
    setForm(emptyForm);
    setEditingId(null);
    setSelectedPurchase(null);
    setShowForm(true);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const amount = parseFloat(form.balance);
    const items = form.items
      .map((item) => ({
        name: item.name.trim(),
        quantity: item.quantity,
      }))
      .filter((item) => item.name);

    if (items.length === 0 || isNaN(amount)) return;

    const primaryItem = items[0];
    const purchaseData = {
      // `items` is the source of truth for a multi-item purchase.
      items,
      // Keep these legacy-compatible fields populated for the existing Assets
      // Report and for any older device that still reads a single item.
      name: primaryItem.name,
      quantity: getTotalQuantity(items),
      bank: form.vendor.trim(),
      vendor: form.vendor.trim(),
      balance: amount,
      purchaseDate: form.purchaseDate,
      papers: form.papers.trim(),
      updatedAt: new Date().toISOString(),
    };

    if (editingId !== null) {
      const updated = purchases.map((purchase, index) =>
        (purchase.id ?? index) === editingId
          ? { ...purchase, ...purchaseData }
          : purchase
      );
      savePurchases(updated);
      setSelectedPurchase((current) =>
        current && (current.id ?? purchases.indexOf(current)) === editingId
          ? { ...current, ...purchaseData }
          : current
      );
    } else {
      savePurchases([{ id: Date.now(), ...purchaseData }, ...purchases]);
    }

    resetForm();
  };

  const beginEdit = (purchase, index) => {
    setEditingId(purchase.id ?? index);
    setForm({
      items: getPurchaseItems(purchase).map((item) => ({
        name: item.name || "",
        quantity: item.quantity ?? "",
      })),
      vendor: purchase.vendor || purchase.bank || "",
      balance: purchase.balance ?? "",
      purchaseDate: purchase.purchaseDate || "",
      papers: purchase.papers || "",
    });
    setSelectedPurchase(null);
    setShowForm(true);
  };

  const deletePurchase = (purchase, index) => {
    if (!window.confirm(`Are you sure you want to delete "${purchase.name}"?`)) return;
    const purchaseId = purchase.id ?? index;
    savePurchases(
      purchases.filter((item, itemIndex) => (item.id ?? itemIndex) !== purchaseId)
    );
    if ((selectedPurchase?.id ?? -1) === purchaseId) setSelectedPurchase(null);
    if (editingId === purchaseId) resetForm();
  };

  const totalPaid = purchases.reduce(
    (sum, purchase) => sum + (parseFloat(purchase.balance) || 0),
    0
  );
  const totalQuantity = purchases.reduce(
    (sum, purchase) => sum + getTotalQuantity(getPurchaseItems(purchase)),
    0
  );

  // Compute per-item summary: count and total weight for each item type
  const itemSummary = {};
  purchases.forEach((purchase) => {
    getPurchaseItems(purchase).forEach((item) => {
      if (!item.name) return;
      if (!itemSummary[item.name]) {
        itemSummary[item.name] = { count: 0, totalWeight: 0 };
      }
      itemSummary[item.name].count += 1;
      itemSummary[item.name].totalWeight += parseFloat(item.quantity) || 0;
    });
  });
  const sortedItems = Object.entries(itemSummary).sort((a, b) =>
    b[1].totalWeight - a[1].totalWeight
  );

  return (
    <div className="table-container">
      <h2>Assets</h2>

      <div className="form" style={{ display: "flex", gap: "8px", alignItems: "center" }}>
        <button onClick={beginAdd}>Add</button>
        <button
          type="button"
          onClick={() => { setShowItemsPanel((v) => !v); setShowForm(false); }}
        >
          Items
        </button>
      </div>

      {showItemsPanel && (
        <div className="pm-form" style={{ marginBottom: "16px" }}>
          <strong style={{ marginBottom: "8px", display: "block" }}>Manage Gold Item Types</strong>
          <div style={{ display: "flex", gap: "8px", marginBottom: "12px" }}>
            <input
              className="pm-input"
              placeholder="New item (e.g. Ring)"
              value={newItemType}
              onChange={(e) => setNewItemType(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); handleAddItemType(); } }}
              style={{ flex: 1 }}
            />
            <button type="button" onClick={handleAddItemType}>Add</button>
          </div>
          {goldItemTypes.length === 0 ? (
            <p className="gold-item-type-empty">No items defined yet. Add some above.</p>
          ) : (
            <div className="gold-item-type-list">
              {goldItemTypes.map((item) => (
                <div key={item} className="gold-item-type-chip">
                  <span>{item}</span>
                  <button
                    type="button"
                    className="gold-item-type-remove"
                    onClick={() => handleRemoveItemType(item)}
                  >×</button>
                </div>
              ))}
            </div>
          )}
          <button type="button" className="pm-btn" style={{ marginTop: "12px" }} onClick={() => setShowItemsPanel(false)}>Done</button>
        </div>
      )}

      <h3>History</h3>
      <div className="table-scroll">
        <table className="responsive-table gold-table">
          <thead>
            <tr>
              <th className="col-vendor">Vendor</th>
              <th className="col-item">Item</th>
              <th className="col-date">Date</th>
              <th className="col-actions">Actions</th>
            </tr>
          </thead>
          <tbody>
            {purchases.length === 0 ? (
                <tr><td colSpan="4">No gold purchases added.</td></tr>
            ) : purchases.map((purchase, index) => {
              const itemNames = getPurchaseItems(purchase)
                .map((item) => item.name)
                .filter(Boolean);
              return (
                <tr key={purchase.id ?? index}>
                  <td>{purchase.vendor || purchase.bank || "-"}</td>
                  <td>
                    {itemNames.length > 0
                      ? itemNames.map((itemName, itemIndex) => (
                          <div key={itemIndex}>{itemName}</div>
                        ))
                      : "-"}
                  </td>
                  <td>{formatDate(purchase.purchaseDate)}</td>
                  <td className="action-buttons">
                    <button onClick={() => setSelectedPurchase((current) => current === purchase ? null : purchase)}>
                      {selectedPurchase === purchase ? "Hide Details" : "Details"}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showForm && (
        <form className="pm-form" onSubmit={handleSubmit}>
          <input className="pm-input" name="vendor" placeholder="vendor" value={form.vendor} onChange={handleChange} />
          <input className="pm-input" type="number" min="0" step="any" name="balance" placeholder="Purchase amount (₹)" value={form.balance} onChange={handleChange} required />
          {form.balance !== "" && <small className="amount-preview">{formatRupee(form.balance)}</small>}
          <input className="pm-input" type="date" name="purchaseDate" value={form.purchaseDate} onChange={handleChange} />
          <input className="pm-input" name="papers" placeholder="Notes / papers" value={form.papers} onChange={handleChange} />

          <div className="gold-items-group">
            <strong className="gold-items-title">Gold Items</strong>
            {goldItemTypes.length === 0 && (
              <p style={{ fontSize: "12px", color: "#e53935", margin: "4px 0 8px" }}>
                ⚠ No item types defined. Use the <strong>Items</strong> button to add item types first.
              </p>
            )}
            {form.items.map((item, index) => (
              <div className="gold-item-row" key={index}>
                <span className="gold-item-index">#{index + 1}</span>
                {goldItemTypes.length > 0 ? (
                  <select
                    className="pm-input"
                    value={item.name}
                    onChange={(event) => handleItemChange(index, "name", event.target.value)}
                    required
                    style={{ flex: 1 }}
                  >
                    <option value="">Select item</option>
                    {goldItemTypes.map((type) => (
                      <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                ) : (
                  <input className="pm-input" placeholder="Gold item (e.g. Ring)" value={item.name} onChange={(event) => handleItemChange(index, "name", event.target.value)} required />
                )}
                <input className="pm-input" type="number" min="0" step="any" placeholder="Quantity (g)" value={item.quantity} onChange={(event) => handleItemChange(index, "quantity", event.target.value)} />
                {form.items.length > 1 && <button type="button" className="delete-btn" onClick={() => removeItem(index)}>Remove</button>}
              </div>
            ))}
            <button type="button" className="gold-add-item-btn" onClick={addItem}>+ Add Item</button>
          </div>

          <div className="pm-actions">
            <button className="add-button pm-btn" type="submit">{editingId !== null ? "Save" : "Add "}</button>
            {editingId !== null && (
              <button
                className="pm-btn pm-detail-btn--delete"
                type="button"
                onClick={() => {
                  const index = purchases.findIndex(
                    (purchase, purchaseIndex) => (purchase.id ?? purchaseIndex) === editingId
                  );
                  if (index !== -1) deletePurchase(purchases[index], index);
                }}
              >
                Delete
              </button>
            )}
            <button className="pm-btn" type="button" onClick={resetForm}>Cancel</button>
          </div>
        </form>
      )}

      {selectedPurchase && (
        <div>
          <h3>Details</h3>
          <table className="responsive-table"><tbody>
            <tr><th>Vendor</th><td>{selectedPurchase.vendor || selectedPurchase.bank || "-"}</td></tr>
            <tr><th>Total Quantity</th><td>{getTotalQuantity(getPurchaseItems(selectedPurchase))} g</td></tr>
            <tr><th>Purchase</th><td>{formatRupee(selectedPurchase.balance)}</td></tr>
            <tr><th>Date</th><td>{formatDate(selectedPurchase.purchaseDate)}</td></tr>
            <tr><th>Notes / Papers</th><td>{selectedPurchase.papers || "-"}</td></tr>
          </tbody></table>
          <h4>Items</h4>
          <table className="responsive-table">
            <thead><tr><th>Item</th><th>Quantity</th></tr></thead>
            <tbody>
              {getPurchaseItems(selectedPurchase).map((item, index) => (
                <tr key={index}>
                  <td>{item.name || "-"}</td>
                  <td>{item.quantity ? `${item.quantity} g` : "-"}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div style={{ display: 'flex', gap: '8px' }}>
            <button
              onClick={() => {
                const index = purchases.findIndex(
                  (purchase, purchaseIndex) =>
                    (purchase.id ?? purchaseIndex) === (selectedPurchase.id ?? purchases.indexOf(selectedPurchase))
                );
                if (index !== -1) beginEdit(selectedPurchase, index);
              }}
            >
              Edit
            </button>
            <button onClick={() => setSelectedPurchase(null)}>Close</button>
          </div>
        </div>
      )}

      {purchases.length > 0 && (
        <div>
          <h3>Summary</h3>

          {/* 8g Gold Price Input */}
          <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "12px" }}>
            <label style={{ fontSize: "13px", fontWeight: "600", whiteSpace: "nowrap" }}>8g Gold Price (₹)</label>
            <input
              type="number"
              className="pm-input"
              placeholder="e.g. 50000"
              value={price8g}
              onChange={(e) => handlePrice8gChange(e.target.value)}
              style={{ maxWidth: "160px" }}
            />
          </div>

          {/* Overall Summary */}
          {(() => {
            const pricePerGram = price8g ? parseFloat(price8g) / 8 : 0;
            const totalValue = pricePerGram > 0 ? totalQuantity * pricePerGram : 0;
            const yearlyReturn = totalValue * 0.10;
            return (
              <table className="responsive-table"><tbody>
                <tr><th>Purchases</th><td>{purchases.length}</td></tr>
                <tr><th>Total Weight</th><td>{totalQuantity} g</td></tr>
                <tr><th>Total Amount</th><td>{formatRupee(totalPaid)}</td></tr>
                {pricePerGram > 0 && (
                  <tr><th>Current Value</th><td>{formatRupee(totalValue)}</td></tr>
                )}
                {pricePerGram > 0 && (
                  <tr style={{ background: "#eaf3ef" }}>
                    <th>📈 Est. 1yr Return (10%)</th>
                    <td style={{ fontWeight: "700", color: "#376c58" }}>{formatRupee(yearlyReturn)}</td>
                  </tr>
                )}
              </tbody></table>
            );
          })()}

          {/* Per-Item Breakdown */}
          {sortedItems.length > 0 && (
            <>
              <h4 style={{ marginTop: "16px", marginBottom: "8px" }}>Detailed Summary</h4>
              <table className="responsive-table"><tbody>
                <tr>
                  <th>Item</th>
                  <th style={{ textAlign: "right" }}>Count</th>
                  <th style={{ textAlign: "right" }}>Total Weight</th>
                </tr>
                {sortedItems.map(([itemName, data]) => (
                  <tr key={itemName}>
                    <td>{itemName}</td>
                    <td style={{ textAlign: "right" }}>{data.count}</td>
                    <td style={{ textAlign: "right" }}>{data.totalWeight.toFixed(2)} g</td>
                  </tr>
                ))}
              </tbody></table>
            </>
          )}
        </div>
      )}
    </div>
  );
};

export default GoldAssetsComponent;
