import { useEffect, useState } from "react";
import { Route, Routes } from "react-router-dom";
import "./App.css";
import AddRowComponent from "./components/AddRowComponent";
import DynamicTable from "./components/DynamicTable";
import EditRowComponent from "./components/EditRowComponent";
import ImportLocalStorage from "./components/ImportLocalStorage";
import MData from "./components/MData";
import CalculatorComponent from "./components/CalculatorComponent";
import BankComponent from "./components/BankComponent";
import GoldAssetsComponent from "./components/GoldAssetsComponent";
import AssetsReportComponent from "./components/AssetsReportComponent";
import PasswordManagerComponent from "./components/PasswordManagerComponent";
import SettingsComponent from "./components/SettingsComponent";
import SyncComponent from "./components/SyncComponent";
import Test from "./components/Test";
import TilesComponent from "./components/TilesComponent";
import TodoComponent from "./components/TodoComponent";

const ASSET_KEYS = [
  { key: "balance_tracker_bank" },
  { key: "balance_tracker_mutual_fund" },
  { key: "balance_tracker_us_mutual_fund" },
  { key: "balance_tracker_btc" },
  { key: "balance_tracker_real_estate" },
  { key: "balance_tracker_business" },
  { key: "balance_tracker_gold", isGold: true },
  { key: "lending", isLend: true },
];

function computeYearlyReturn() {
  const gold8gPrice = parseFloat(localStorage.getItem("gold_price_8g")) || 0;
  const goldPricePerGram = gold8gPrice / 8;

  let estReturn = 0;
  let lendPayment = 0;

  ASSET_KEYS.forEach(({ key, isGold, isLend }) => {
    try {
      const entries = JSON.parse(localStorage.getItem(key) || "[]");
      if (isLend) {
        lendPayment = entries.reduce((sum, e) => {
          const amt = parseFloat(e.paymentAmount) || 0;
          if (e.paymentType === "m") return sum + amt * 12;
          if (e.paymentType === "y") return sum + amt;
          return sum;
        }, 0);
      } else if (isGold && goldPricePerGram > 0) {
        const totalWeight = entries.reduce((sum, e) => {
          const items = Array.isArray(e.items) && e.items.length > 0 ? e.items : [{ quantity: e.quantity }];
          return sum + items.reduce((s, i) => s + (parseFloat(i.quantity) || 0), 0);
        }, 0);
        estReturn += totalWeight * goldPricePerGram * 0.1;
      } else {
        estReturn += entries.reduce((sum, e) => sum + (e.balance || 0) * (e.estimatedReturn || 0) / 100, 0);
      }
    } catch {}
  });

  return estReturn - lendPayment;
}

function App() {
  const [darkMode, setDarkMode] = useState(() => {
    const savedMode = localStorage.getItem("darkMode");
    return savedMode === "true";
  });

  const [yearlyReturn, setYearlyReturn] = useState(() => computeYearlyReturn());

  useEffect(() => {
    setYearlyReturn(computeYearlyReturn());
  }, []);

  // Apply dark mode class to body element
  useEffect(() => {
    if (darkMode) {
      document.body.classList.add("dark-mode");
    } else {
      document.body.classList.remove("dark-mode");
    }
    localStorage.setItem("darkMode", darkMode);
  }, [darkMode]);

  const toggleDarkMode = () => {
    setDarkMode((prevMode) => !prevMode);
  };

  const tiles = [
    { path: "/today", label: "Today" },
    { path: "/it", label: "IT" },
    { path: "/assets", label: "Assets" },
    { path: "/password-manager", label: "Manager" },
    { path: "/component-problems", label: "Solitude" },
    { path: "/settings", label: "Settings" },
  ];

  const todayTiles = [
    { path: "/component-bucket", label: "Bucket" },
    { path: "/component-t", label: "Today" },
    { path: "/personal-improvement", label: "Personal Improvement" },
    { path: "/mistake", label: "Mistake" },
    { path: "/learning", label: "Learning" },
    { path: "/focus", label: "Focus" },
    { path: "/goal", label: "Goal" },
    { path: "/quotes", label: "Motivation" },
    { path: "/family", label: "Family" },
  ];

  const stockTiles = [
    { path: "/component-s", label: "Stock" },
    { path: "/component-m", label: "MF" },
    { path: "/calculator", label: "Calculator" },
    { path: "/stock-notes", label: "Notes" },
  ];

  const itTiles = [
    { path: "/component-i-main", label: "IT Service" },
    { path: "/it-notes", label: "Notes" },
  ];

  const goldTiles = [
    { path: "/component-g2-main", label: "G Calculator" },
    { path: "/gold-notes", label: "Notes" },
  ];

  const realTiles = [
    { path: "/component-r-main", label: "Real Service" },
    { path: "/real-mistake", label: "Mistake" },
    { path: "/real-learning", label: "Learning" },
  ];

  const lendingTiles = [
    { path: "/component-l-main", label: "Lend" },
    { path: "/bank", label: "Bank" },
    { path: "/mutual-fund", label: "MF" },
    { path: "/us-mf", label: "US MF" },
    { path: "/btc", label: "BTC" },
    { path: "/gold-assets", label: "Gold" },
    { path: "/real-estate", label: "Real estate" },
    { path: "/business", label: "Business" },
    { path: "/assets-service", label: "Services" },
    { path: "/lending-notes", label: "Notes" },
    { path: "/assets-report", label: "Report" },
  ];

  const serviceTiles = [
    { path: "/component-s", label: "Stock" },
    { path: "/calculator", label: "S calculator" },
    { path: "/component-g2-main", label: "G calculator" },
  ];

  const goalTiles = [
    { path: "/today-goal", label: "Today" },
    { path: "/week-goal", label: "Week" },
    { path: "/month-goal", label: "Month" },
  ];

  return (
    <div className="counter-app">
      <Routes>
        <Route
          path="/"
          element={<TilesComponent tiles={tiles} />}
        />
        <Route path="/today" element={<TilesComponent tiles={todayTiles} />} />
        <Route path="/stock" element={<TilesComponent tiles={stockTiles} />} />
        <Route path="/it" element={<TilesComponent tiles={itTiles} />} />
        <Route path="/gold" element={<TilesComponent tiles={goldTiles} />} />
        <Route path="/real" element={<TilesComponent tiles={realTiles} />} />
        <Route
          path="/assets"
          element={<TilesComponent tiles={lendingTiles} yearlyReturn={yearlyReturn} />}
        />
        <Route
          path="/assets-service"
          element={<TilesComponent tiles={serviceTiles} />}
        />
        <Route path="/goal" element={<TilesComponent tiles={goalTiles} />} />
        <Route
          path="/settings"
          element={
            <SettingsComponent
              darkMode={darkMode}
              toggleDarkMode={toggleDarkMode}
            />
          }
        />
        <Route path="/sync" element={<SyncComponent />} />

        {/* Password Manager route */}
        <Route
          path="/password-manager"
          element={<PasswordManagerComponent />}
        />

        {/* Stock section routes */}
        <Route path="/component-s" element={<MData />} />
        <Route path="/calculator" element={<CalculatorComponent />} />
        <Route
          path="/component-m"
          element={<DynamicTable filter="mf" name="MF" />}
        />

        <Route
          path="/component-i-main"
          element={<TodoComponent filter="it-service" name="IT Service" />}
        />
        <Route
          path="/it-notes"
          element={<TodoComponent filter="it-notes" name="IT Notes" />}
        />

        <Route
          path="/stock-notes"
          element={<TodoComponent filter="stock-notes" name="Stock Notes" />}
        />

        {/* Gold section routes */}
        <Route path="/component-g2-main" element={<Test />} />
        <Route
          path="/gold-notes"
          element={<TodoComponent filter="gold-notes" name="Gold Notes" />}
        />

        {/* Real section routes */}
        <Route
          path="/component-r-main"
          element={<TodoComponent filter="real" name="R-Service" />}
        />
        <Route
          path="/real-mistake"
          element={
            <TodoComponent filter="real-mistake" name="Real Estate Mistakes" />
          }
        />
        <Route
          path="/real-learning"
          element={
            <TodoComponent filter="real-learning" name="Real Estate Learning" />
          }
        />

        {/* Lending section routes */}
        <Route
          path="/component-l-main"
          element={<DynamicTable filter="lending" name="Lending" />}
        />
        <Route path="/bank" element={<BankComponent headLine="Bank"/>} />
        <Route path="/mutual-fund" element={<BankComponent headLine="Mutual Fund"/>} />
        <Route path="/us-mf" element={<BankComponent headLine="US Mutual Fund"/>} />
        <Route path="/btc" element={<BankComponent headLine="BTC"/>} />
        <Route path="/gold-assets" element={<GoldAssetsComponent />} />
        <Route path="/real-estate" element={<BankComponent headLine="Real Estate"/>} />
        <Route path="/business" element={<BankComponent headLine="Business"/>} />
        <Route path="/assets-report" element={<AssetsReportComponent />} />
        <Route
          path="/lending-notes"
          element={<TodoComponent filter="lending-notes" name="Notes" />}
        />

        {/* Legacy routes for backward compatibility */}
        <Route path="/component-g2" element={<Test />} />
        <Route
          path="/component-r"
          element={<TodoComponent filter="real" name="R-Service" />}
        />
        <Route
          path="/component-i"
          element={<TodoComponent filter="it" name="IT-Service" />}
        />
        <Route
          path="/component-l"
          element={<DynamicTable filter="lending" name="Lending" />}
        />

        <Route
          path="/component-t"
          element={<TodoComponent filter="today" name="Today" />}
        />
        <Route
          path="/component-b"
          element={<DynamicTable filter="bank" name="Bank" />}
        />
        <Route path="//importJson" element={<ImportLocalStorage />} />
        <Route path="/add-row" element={<AddRowComponent name="Lending" />} />
        <Route path="/edit-row" element={<EditRowComponent />} />
        {/* Additional Routes */}
        <Route
          path="/personal-improvement"
          element={
            <TodoComponent filter="personal-improvement" name="Improvement" />
          }
        />
        <Route
          path="/learning"
          element={<TodoComponent filter="learning" name="Learning" />}
        />
        <Route
          path="/mistake"
          element={<TodoComponent filter="mistake" name="Mistake" />}
        />
        <Route
          path="/focus"
          element={<TodoComponent filter="focus" name="Focus" />}
        />
        <Route
          path="/component-problems"
          element={
            <TodoComponent filter="problems" name="Tell me your Problems" />
          }
        />
        <Route
          path="/component-bucket"
          element={<TodoComponent filter="bucket" name="Bucket" />}
        />
        <Route
          path="/family"
          element={<TodoComponent filter="family" name="Family goal" />}
        />

        <Route
          path="/quotes"
          element={<TodoComponent filter="quotes" name="Quotes" />}
        />

        {/* goal router */}
        <Route
          path="/today-goal"
          element={<TodoComponent filter="t-goal" name="Now" />}
        />
        <Route
          path="/week-goal"
          element={<TodoComponent filter="w-goal" name="Week" />}
        />
        <Route
          path="/month-goal"
          element={<TodoComponent filter="=m-goal" name="Month" />}
        />
      </Routes>
    </div>
  );
}

export default App;
