import { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import "../App.css";

const ASSET_SOURCES = [
  { key: "balance_tracker_bank",          label: "Bank",          color: "#376c58", icon: "🏦", route: "/bank" },
  { key: "balance_tracker_mutual_fund",   label: "Mutual Fund",   color: "#1a6fb5", icon: "📈", route: "/mutual-fund" },
  { key: "balance_tracker_us_mutual_fund",label: "US Mutual Fund",color: "#0d47a1", icon: "🇺🇸", route: "/us-mf" },
  { key: "balance_tracker_btc",           label: "BTC",           color: "#f57c00", icon: "₿",  route: "/btc" },
  { key: "balance_tracker_gold",          label: "Gold",          color: "#c8a000", icon: "🪙", route: "/gold-assets" },
  { key: "balance_tracker_real_estate",   label: "Real Estate",   color: "#795548", icon: "🏠", route: "/real-estate" },
  { key: "balance_tracker_business",      label: "Business",      color: "#6f42c1", icon: "💼", route: "/business" },
  { key: "lending",                       label: "Lend",          color: "#00897b", icon: "🤝", route: "/component-l-main", isLend: true },
];

const AssetsReportComponent = () => {
  const navigate = useNavigate();
  const formatCurrency = (val) =>
    val.toLocaleString("en-IN", { maximumFractionDigits: 2 });

  const assets = useMemo(() => {
    // Read gold 8g price for return calculation
    const gold8gPrice = parseFloat(localStorage.getItem("gold_price_8g")) || 0;
    const goldPricePerGram = gold8gPrice / 8;

    return ASSET_SOURCES.map((src) => {
      try {
        const raw = localStorage.getItem(src.key);
        const entries = raw ? JSON.parse(raw) : [];
        const total = entries.reduce((sum, e) => sum + (e.balance || 0), 0);

        let estimatedYearlyReturn = 0;

        if (src.key === "balance_tracker_gold" && goldPricePerGram > 0) {
          // Gold: calculate based on total weight × price per gram × 10%
          // Mirrors getPurchaseItems logic: Array.isArray(e.items) → e.items, else old single-item format
          const totalWeight = entries.reduce((sum, e) => {
            const items = Array.isArray(e.items) && e.items.length > 0
              ? e.items
              : [{ quantity: e.quantity }];
            return sum + items.reduce((s, i) => s + (parseFloat(i.quantity) || 0), 0);
          }, 0);
          estimatedYearlyReturn = totalWeight * goldPricePerGram * 0.10;
        } else {
          // Other assets: use per-entry estimatedReturn %
          estimatedYearlyReturn = entries.reduce((sum, e) => {
            const rate = e.estimatedReturn || 0;
            return sum + (e.balance || 0) * rate / 100;
          }, 0);
        }

        if (src.isLend) {
          // Lend: total = sum of lent amounts, yearlyPayment = yearly repayment schedule
          const lendTotal = entries.reduce((sum, e) => sum + (parseFloat(e.balance) || 0), 0);
          const yearlyPayment = entries.reduce((sum, e) => {
            const amt = parseFloat(e.paymentAmount) || 0;
            if (e.paymentType === 'm') return sum + amt * 12;
            if (e.paymentType === 'y') return sum + amt;
            return sum;
          }, 0);
          return { ...src, entries, total: lendTotal, estimatedYearlyReturn: 0, yearlyPayment };
        }

        return { ...src, entries, total, estimatedYearlyReturn, yearlyPayment: 0 };
      } catch {
        return { ...src, entries: [], total: 0, estimatedYearlyReturn: 0, yearlyPayment: 0 };
      }
    });
  }, []);

  const grandTotal = assets.reduce((sum, a) => a.isLend ? sum : sum + a.total, 0);
  const grandEstimatedReturn = assets.reduce((sum, a) => sum + a.estimatedYearlyReturn, 0);
  const grandYearlyPayment = assets.find(a => a.isLend)?.yearlyPayment || 0;
  const grandYearlyTotal = grandEstimatedReturn - grandYearlyPayment;

  return (
    <div className="counter-app">
      <div className="todo-container">
        <h1>Report</h1>

        {/* Grand Total Card */}
        <div
          style={{
            backgroundColor: "#376c58",
            borderRadius: "12px",
            padding: "16px 20px",
            marginBottom: "20px",
            color: "#fff",
          }}
        >
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontSize: "15px", fontWeight: "600" }}>Net Worth</span>
            <span style={{ fontSize: "20px", fontWeight: "700" }}>
              ₹{formatCurrency(grandTotal)}
            </span>
          </div>
          {grandEstimatedReturn > 0 && (
            <div style={{
              display: "flex", justifyContent: "space-between", alignItems: "center",
              marginTop: "8px", paddingTop: "8px", borderTop: "1px solid rgba(255,255,255,0.3)"
            }}>
              <span style={{ fontSize: "13px", opacity: 0.9 }}> Est. Yearly Return</span>
              <span style={{ fontSize: "16px", fontWeight: "600" }}>
                ₹{formatCurrency(grandEstimatedReturn)}
              </span>
            </div>
          )}
          {grandYearlyPayment > 0 && (
            <div style={{
              display: "flex", justifyContent: "space-between", alignItems: "center",
              marginTop: "6px", paddingTop: "6px", borderTop: "1px solid rgba(255,255,255,0.2)"
            }}>
              <span style={{ fontSize: "13px", opacity: 0.9 }}>Lend Yearly Payment</span>
              <span style={{ fontSize: "16px", fontWeight: "600" }}>
                ₹{formatCurrency(grandYearlyPayment)}
              </span>
            </div>
          )}
          {(grandEstimatedReturn > 0 || grandYearlyPayment > 0) && (
            <div style={{
              display: "flex", justifyContent: "space-between", alignItems: "center",
              marginTop: "6px", paddingTop: "6px", borderTop: "1px solid rgba(255,255,255,0.4)"
            }}>
              <span style={{ fontSize: "14px", fontWeight: "700" }}>Grand Yearly Return</span>
              <span style={{ fontSize: "18px", fontWeight: "800", color: grandYearlyTotal >= 0 ? "#fff" : "#ffcccc" }}>
                {grandYearlyTotal >= 0 ? "+" : ""}₹{formatCurrency(Math.abs(grandYearlyTotal))}
              </span>
            </div>
          )}
        </div>

        {/* Asset Summary Cards */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))",
            gap: "10px",
            marginBottom: "24px",
          }}
        >
          {assets.map((asset) => (
            <div
              key={asset.key}
              onClick={() => navigate(asset.route)}
              style={{
                backgroundColor: "#f9f9f9",
                border: `2px solid ${asset.color}22`,
                borderRadius: "10px",
                padding: "12px",
                textAlign: "center",
                cursor: "pointer",
                transition: "transform 0.15s, box-shadow 0.15s",
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = "translateY(-2px)";
                e.currentTarget.style.boxShadow = `0 4px 12px ${asset.color}33`;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = "translateY(0)";
                e.currentTarget.style.boxShadow = "none";
              }}
            >
              <div style={{ fontSize: "22px", marginBottom: "4px" }}>{asset.icon}</div>
              <div style={{ fontSize: "12px", color: "#666", marginBottom: "4px" }}>{asset.label}</div>
              <div style={{ fontSize: "14px", fontWeight: "700", color: asset.color }}>
                ₹{formatCurrency(asset.total)}
              </div>
              <div style={{ fontSize: "11px", color: "#999", marginTop: "2px" }}>
                {asset.entries.length} {asset.entries.length === 1 ? "entry" : "entries"}
              </div>
              {asset.isLend && asset.yearlyPayment > 0 && (
                <div style={{ fontSize: "11px", color: asset.color, marginTop: "4px", fontWeight: "600" }}>
                  📥 ₹{formatCurrency(asset.yearlyPayment)}/yr payment
                </div>
              )}
              {!asset.isLend && asset.estimatedYearlyReturn > 0 && (
                <div style={{ fontSize: "11px", color: asset.color, marginTop: "4px", fontWeight: "600" }}>
                  +₹{formatCurrency(asset.estimatedYearlyReturn)}/yr
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Portfolio % Bar */}
        {grandTotal > 0 && (
          <div style={{ marginBottom: "24px" }}>
            <div style={{ fontSize: "13px", fontWeight: "600", color: "#444", marginBottom: "8px" }}>
              Portfolio Breakdown
            </div>
            <div style={{ display: "flex", borderRadius: "8px", overflow: "hidden", height: "20px" }}>
              {assets.filter(a => a.total > 0).map((asset) => (
                <div
                  key={asset.key}
                  title={`${asset.label}: ${((asset.total / grandTotal) * 100).toFixed(1)}%`}
                  style={{
                    width: `${(asset.total / grandTotal) * 100}%`,
                    backgroundColor: asset.color,
                    transition: "width 0.3s",
                  }}
                />
              ))}
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "8px", marginTop: "8px" }}>
              {assets.filter(a => a.total > 0).map((asset) => (
                <div key={asset.key} style={{ display: "flex", alignItems: "center", gap: "4px", fontSize: "11px", color: "#555" }}>
                  <span style={{ width: "10px", height: "10px", borderRadius: "50%", backgroundColor: asset.color, display: "inline-block" }} />
                  {asset.label} ({((asset.total / grandTotal) * 100).toFixed(1)}%)
                </div>
              ))}
            </div>
          </div>
        )}

        {grandTotal === 0 && (
          <p style={{ textAlign: "center", color: "#999", marginTop: "40px" }}>
            No asset data found. Add entries in Bank, MF, US MF, BTC or Gold.
          </p>
        )}
      </div>
    </div>
  );
};

export default AssetsReportComponent;
